// PS side of the CSR test UC3 (Zynq profile, point 4): stuck program.
// The Cortex-A9 #0 loads and runs a CPU program that never writes DONE, as in UC1.
// csr_wait() ends with a timeout while STATUS is still BUSY and the CPU is still running,
// then RESET CPU stops the CPU anyway.
// The CPU side is sw/SoC/examples/ps_csr_uc3.
#include <stdint.h>
#include "ps_hw.h"        // generated by build_ps_app.py from the XSA
#include "cpu_program.h"  // generated by build_ps_app.py from the CPU program
#include "xil_printf.h"
#include "simplyv_conf.h"
#include "simplyv_csr_host.h"
#include "ps_csr_uc3.h"

// Reads of STATUS before the timeout
#define MAX_POLLS   (3000000u)
// Reads of STATUS used as a delay, to see if the counter of the CPU moves
#define DELAY_POLLS (100000u)

// The CPU program is linked at the start of BRAM_0
#define BOOT_ADDR ((uint32_t)_peripheral_BRAM_0_start)

// Name of a state, for the prints
static const char *state_name(uint32_t status)
{
    switch (status) {
        case CSR_ST_IDLE:  return "IDLE";
        case CSR_ST_BUSY:  return "BUSY";
        case CSR_ST_DONE:  return "DONE";
        case CSR_ST_ERROR: return "ERROR";
        case CSR_ST_HALT:  return "HALT";
        case CSR_TIMEOUT:  return "TIMEOUT";
        default:           return "UNKNOWN";
    }
}

// Wait some time, reading STATUS
static void delay(void)
{
    for (uint32_t i = 0; i < DELAY_POLLS; i++) {
        (void)csr_status();
    }
}

int main(void)
{
    // Boot address and data in BRAM_0, as seen by the PS
    volatile uint32_t *program = (volatile uint32_t *)(uintptr_t)(PS_M_AXI_GP0_BASEADDR + BOOT_ADDR);
    uint32_t cpu_data = (uint32_t)(_peripheral_BRAM_0_start + PS_CSR_DATA_OFFSET);
    volatile uint32_t *data = (volatile uint32_t *)(uintptr_t)(PS_M_AXI_GP0_BASEADDR + cpu_data);
    uint32_t ptr_in  = cpu_data + 4u * PS_CSR_IN;
    uint32_t ptr_out = cpu_data + 4u * PS_CSR_OUT;
    uint32_t status;
    uint32_t errors = 0;
    uint32_t count_a;
    uint32_t count_b;

    xil_printf("[PS] CSR at 0x%08x, STATUS %s\r\n", (uint32_t)CSR_HOST_BASEADDR, state_name(csr_status()));

    // The program must not overlap the data
    if (BOOT_ADDR + 4u * CPU_PROGRAM_WORDS > cpu_data) {
        xil_printf("[PS] ERROR: program of %u bytes overlaps the data\r\n", 4u * CPU_PROGRAM_WORDS);
        return 1;
    }

    // 1. Stop the CPU
    csr_reset_cpu();
    status = csr_status();
    xil_printf("[PS] RESET CPU       -> STATUS %s\r\n", state_name(status));
    if (status != CSR_ST_IDLE) {
        xil_printf("[PS] ERROR: expected IDLE\r\n");
        return 1;
    }

    // 2. LOAD PROGRAM with the boot address, then copy the program there and read it back
    csr_load_program(BOOT_ADDR);
    for (uint32_t i = 0; i < CPU_PROGRAM_WORDS; i++) {
        program[i] = cpu_program[i];
    }
    for (uint32_t i = 0; i < CPU_PROGRAM_WORDS; i++) {
        if (program[i] != cpu_program[i]) {
            errors++;
        }
    }
    xil_printf("[PS] LOAD PROGRAM    -> STATUS %s (%u bytes at BOOT_ADDR 0x%08x, %u errors on read back)\r\n",
               state_name(csr_status()), 4u * CPU_PROGRAM_WORDS, BOOT_ADDR, errors);
    if (errors != 0) {
        xil_printf("[PS] ERROR: program not written correctly\r\n");
        return 1;
    }

    // 3. Pointers seen by the CPU: the counter is at PTR_OUT
    data[PS_CSR_IN]  = 0;
    data[PS_CSR_OUT] = 0;
    csr_load_input_data(ptr_in, ptr_out);
    xil_printf("[PS] LOAD INPUT DATA -> STATUS %s (PTR_IN 0x%08x, PTR_OUT 0x%08x)\r\n",
               state_name(csr_status()), ptr_in, ptr_out);

    // 4. Start the CPU: it never writes DONE, so the wait ends with a timeout
    csr_run();
    xil_printf("[PS] RUN             -> STATUS %s\r\n", state_name(csr_status()));
    status = csr_wait(MAX_POLLS);
    xil_printf("[PS] Wait            -> %s after %u reads, STATUS %s\r\n",
               state_name(status), MAX_POLLS, state_name(csr_status()));
    if ( (status != CSR_TIMEOUT) || (csr_status() != CSR_ST_BUSY) ) {
        xil_printf("[PS] ERROR: expected TIMEOUT with STATUS BUSY\r\n");
        return 1;
    }

    // 5. The CPU is still running: its counter moves
    count_a = data[PS_CSR_OUT];
    delay();
    count_b = data[PS_CSR_OUT];
    xil_printf("[PS] Counter of the CPU: %u -> %u\r\n", count_a, count_b);
    if (count_b == count_a) {
        xil_printf("[PS] ERROR: expected the CPU to be running\r\n");
        return 1;
    }

    // 6. RESET CPU stops the CPU anyway: its counter does not move
    csr_reset_cpu();
    status = csr_status();
    count_a = data[PS_CSR_OUT];
    delay();
    count_b = data[PS_CSR_OUT];
    xil_printf("[PS] RESET CPU       -> STATUS %s, counter of the CPU: %u -> %u\r\n",
               state_name(status), count_a, count_b);
    if ( (status != CSR_ST_IDLE) || (count_b != count_a) ) {
        xil_printf("[PS] ERROR: expected IDLE and the CPU stopped\r\n");
        return 1;
    }

    xil_printf("[PS] Test passed\r\n");
    return 0;
}
